SELECT e.tenant_id, e.asset_id AS entity_id, e.event_id AS evidence_ids FROM events e WHERE e.phase=1 AND e.domain='endpoint' AND e.action='process_launch' AND e.process='powershell.exe' AND e.parent IN ('winword.exe','excel.exe','mshta.exe') AND NOT EXISTS (SELECT 1 FROM events b WHERE b.phase=0 AND b.tenant_id=e.tenant_id AND b.asset_id=e.asset_id AND b.parent=e.parent AND b.process=e.process);
